import os, re

def load_grids():
    """Load grid data from this instance's session log"""
    rlm_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not rlm_dir:
        # Try common fallback
        rlm_dir = os.environ.get('RLM_SESSION_DIR vợ thuộc')

    d = rlm_dir
    if not d or not os.path.exists(d):
        print(f"No session dir: {d}")
        return {}

    session_file = os.path.join(d, '..', 'sessions', os.path.basename(d) + '.jsonl')
    # Also try different paths
    for sess_path in [
        d + '/../../sessions/' + os.path.basename(d) + '.jsonl',
    ]:
        if os.path.exists(sess_path):
            session_file = sess_path
            break

    if not os.path.exists(session_file):
        print(f"No session file found at: {session_file}")
        return {}

    with open(session_file, 'r') as f:
        content = f.read()

    grids = {}
    # Find demo pairs and test input
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        key = match.group(1)
        h, w = int(match.group(2)), int(match.group(3))
        # Extract grid rows (skip the pattern end to next header)
        after_match = content[match.end():]
        lines = after_match.split('\n')[:h]
        if all(len(l.strip()) == w and all(x.isdigit() for x in l.strip()) for l in lines):
            grids[key] = [[int(x) for x in l.split()] for l in lines]

    return grids

grids = load_grids()
print("Loaded grids:", sorted(grids.keys()))
if grids:
    for k, v in grids.items():
        print(f"\n{k}: {len(v)} rows x {len(v[0])} cols")
        print(v[:3] if len(v) >= 3 else v)
        print(f"... total {len(v)} rows")

