    output = [row[:] for row in grid]
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and (r,c) not in visited:
                q = [(r, c)]
                component = []
                while q:
                    cr, cc = q.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(1,0), (0,1), (-1,0), (0,-1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
